SourceCode.Declaration:
/// <summary>
/// Controller class for processing outbound messages
/// </summary>
[SysOperationJournaledParametersAttribute(true)]
class OMGOutboundMessageProcessController  extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Constructs the class
/// </summary>
/// <returns>The instantiated OMGOutboundMessageProcessController class</returns>
public static OMGOutboundMessageProcessController construct()
{
    SysOperationController controller;

    controller = new OMGOutboundMessageProcessController();

    return controller;
}

/// <summary>
/// Instantiates the class
/// </summary>
protected void new()
{
    super(classStr(OMGOutboundMessageProcessService), methodStr(OMGOutboundMessageProcessService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Public handle for the class. Instantiates it, and kicks off processing
/// </summary>
/// <param name = "_args">Args from the caller</param>
public static void main(Args _args)
{
    OMGOutboundMessageProcessController controller = OMGOutboundMessageProcessController::construct();
    controller.startOperation();

}

/// <summary>
/// The class caption
/// </summary>
/// <returns>The caption</returns>
protected ClassDescription defaultCaption()
{
    return "@OMG:ProcessOutboundMessages";
}
